package engine_test

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/buildfoundry-nz/formwork/internal/config"
	"github.com/buildfoundry-nz/formwork/internal/engine"
	"github.com/buildfoundry-nz/formwork/internal/scan"
)

func genTree(t *testing.T, files map[string]string) ([]*config.Rule, *scan.FileSet) {
	t.Helper()
	root := t.TempDir()
	all := map[string]string{
		".formwork/formwork.yaml": "version: 1\ngenerated:\n  - {marker: 'DO NOT EDIT.', proven_by: [codegen-fresh]}\n",
		".formwork/rules/r.yaml": "rules:\n" +
			"  - id: no-widget\n    type: forbidden-pattern\n    scope: {include: ['**/*.go']}\n    params: {pattern: WIDGET}\n" +
			"  - id: codegen-fresh\n    type: forbidden-pattern\n    scope: {include: ['**/*.go'], generated: true}\n    params: {pattern: WIDGET}\n",
	}
	for k, v := range files {
		all[k] = v
	}
	for rel, content := range all {
		p := filepath.Join(root, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	cfg, err := config.Load(root)
	if err != nil {
		t.Fatal(err)
	}
	fset, err := scan.Walk(root)
	if err != nil {
		t.Fatal(err)
	}
	return cfg.Rules, fset
}

// A file carrying a declared generator header is outside every rule that does
// not declare scope.generated, and inside the one that does. A hand-written
// file is judged by both, whatever it is named.
func TestRunGeneratedFilesAreJudgedOnlyByOptedInRules(t *testing.T) {
	rs, fset := genTree(t, map[string]string{
		"gen.pb.go":   "// Code generated by protoc-gen-go. DO NOT EDIT.\n\npackage p\n\nvar a = WIDGET\n",
		"hand.pb.go":  "package p\n\nvar b = WIDGET\n",
		"quoted.go":   "package p\n\nvar c = \"DO NOT EDIT.\" + WIDGET\n",
		"authored.go": "package p\n\nvar d = WIDGET\n",
	})
	got, err := engine.Run(rs, fset, 1)
	if err != nil {
		t.Fatal(err)
	}
	seen := map[string][]string{}
	for _, f := range got {
		seen[f.RuleID] = append(seen[f.RuleID], f.Path)
	}
	if len(seen["no-widget"]) != 3 {
		t.Fatalf("no-widget judged %v, want the three authored files and never gen.pb.go", seen["no-widget"])
	}
	for _, p := range seen["no-widget"] {
		if p == "gen.pb.go" {
			t.Fatalf("no-widget judged the generated file: %v", seen["no-widget"])
		}
	}
	if len(seen["codegen-fresh"]) != 4 {
		t.Fatalf("codegen-fresh judged %v, want all four: it declares scope.generated", seen["codegen-fresh"])
	}
}
